/**
 * 按观测标识排序锁定多条当前记录（SELECT ... FOR UPDATE），
 * 用于关联观测簇事务在簇级操作前一次性锁定簇内全部观测，避免死锁并串行化并发。
 */
public List<ObservationSnapshot> findCurrentsForUpdateOrdered(List<String> observationIds) {
    if (observationIds.isEmpty()) {
        return List.of();
    }
    String placeholders = String.join(",", observationIds.stream().map(id -> "?").toList());
    return jdbcTemplate.query(
            "SELECT " + SNAPSHOT_COLUMNS + " FROM observation_current WHERE observation_id IN ("
                    + placeholders + ") ORDER BY observation_id ASC FOR UPDATE",
            SNAPSHOT_MAPPER, observationIds.toArray());
}

