                .andExpect(jsonPath("$.reading").value("6.0"));
        Integer versionRows = jdbcTemplate.queryForObject(
                "SELECT COUNT(*) FROM observation_version WHERE observation_id = 'obs-r2'", Integer.class);
        assertThat(versionRows).isEqualTo(3);
