                .andExpect(jsonPath("$.snapshotAfter[0].version").value(3))
                .andExpect(jsonPath("$.snapshotAfter[1].reading").value("3.0"));
        mockMvc.perform(get("/api/observations/{id}", "obs-a"))
                .andExpect(jsonPath("$.deleted").value(true));
